<template>
  <section class="editor" :data-work-order-create="!taskId || undefined" data-work-order-editor>
    <header class="page-head"><div><p>实训任务管理 / {{ taskId ? '编辑任务' : '新建任务' }}</p><h1>{{ taskId ? '综合工单编辑器' : '创建综合工单' }}</h1><span>从资源库组合活动，并设置区块顺序、必做项和评分权重。</span></div><div class="head-actions"><NuxtLink to="/admin/tasks">返回列表</NuxtLink><NuxtLink v-if="taskId" :to="`/admin/tasks/${taskId}/preview`" data-preview-work-order>学生视角预览</NuxtLink></div></header>
    <p v-if="loading" class="state">正在读取班级、资源和工单…</p>
    <p v-else-if="loadError" class="error" role="alert">{{ loadError }}</p>
    <form v-else @submit.prevent="save">
      <fieldset :disabled="saving || published"><legend>基础设置</legend>
        <div class="form-grid"><label>工单名称<input v-model.trim="form.title" data-work-order-title maxlength="120" required /></label><label>发布班级<select v-model="form.classId" data-work-order-class required><option value="" disabled>请选择班级</option><option v-for="item in classes" :key="item.id" :value="item.id">{{ item.name }}（{{ item.studentCount }} 人）</option></select></label><label class="wide">工单说明<textarea v-model.trim="form.description" rows="3" maxlength="2000" /></label><label>自动评分权重<input v-model.number="form.autoScoreWeight" type="number" min="0" max="100" step="1" /></label><label>人工评分权重<input v-model.number="form.manualScoreWeight" type="number" min="0" max="100" step="1" /></label><label>限时（分钟）<input v-model.number="form.timeLimitMinutes" type="number" min="1" step="1" placeholder="不限制" /></label></div>
        <p class="weight-summary" :class="{ invalid: form.autoScoreWeight + form.manualScoreWeight !== 100 }">总评分权重：{{ form.autoScoreWeight + form.manualScoreWeight }}%（必须为 100%）</p>
      </fieldset>

      <section class="resource-library"><header><div><h2>实训资源库</h2><p>资源加入后复制为本工单的独立区块。</p></div><select v-model="resourceSource" aria-label="资源来源"><option value="">全部来源</option><option value="SOFTWARE_CENTER">软件中心</option><option value="SKILL_CAMP">技能训练营</option><option value="ENTERPRISE_TASK_LIBRARY">企业任务库</option></select></header>
        <div class="resource-list"><article v-for="resource in filteredResources" :key="resource.id"><span>{{ sourceLabel(resource.source) }}</span><strong>{{ resource.title }}</strong><p>{{ resource.summary }}</p><button type="button" data-resource-add :disabled="saving || published" @click="addResource(resource)">加入工单</button></article></div>
      </section>

      <section class="sections"><header><div><h2>工单区块编排</h2><p>计分区块总权重必须为 100%。</p></div><div><button type="button" data-add-media :disabled="published" @click="addMedia">添加媒体</button><button type="button" data-add-quiz :disabled="published" @click="addQuiz">添加题目</button></div></header>
        <p v-if="scoringSections.length === 0" class="state">尚未添加活动，请从资源库选择沙盘活动，或添加媒体、题目。</p>
        <article v-for="(section,index) in scoringSections" :key="section.clientKey" class="section-row">
          <div class="section-top"><div><span>{{ typeLabel(section.type) }}</span><input v-model.trim="section.title" aria-label="区块名称" maxlength="120" required /></div><div class="row-actions"><button type="button" :disabled="index === 0" title="上移" @click="move(index,-1)">↑</button><button type="button" :disabled="index === scoringSections.length-1" title="下移" @click="move(index,1)">↓</button><button type="button" title="删除" @click="remove(index)">删除</button></div></div>
          <div class="section-settings"><label>权重<input v-model.number="section.weightPercent" data-section-weight type="number" min="0" max="100" step="1" /></label><label class="check"><input v-model="section.required" type="checkbox" /> 必做</label><label class="grow">说明<input v-model.trim="section.description" maxlength="2000" /></label></div>
          <div v-if="section.type === 'QUIZ'" class="nested-editor">
            <article v-for="(question, questionIndex) in section.questions" :key="questionIndex" class="nested-item">
              <header><strong>题目 {{ questionIndex + 1 }}</strong><button v-if="section.questions!.length > 1" type="button" @click="removeQuestion(section, questionIndex)">删除题目</button></header>
              <div class="detail-grid question-grid">
                <label>题型<select v-model="question.type" @change="changeQuestionType(question)"><option value="SINGLE">单选题</option><option value="MULTIPLE">多选题</option><option value="TRUE_FALSE">判断题</option><option value="FILL_BLANK">填空题</option><option value="SHORT_ANSWER">简答题</option></select></label>
                <label>分值<input v-model.number="question.points" type="number" min="0" max="100" step="1" /></label>
                <label class="wide">题干<textarea v-model.trim="question.prompt" :data-quiz-prompt="questionIndex === 0 || undefined" rows="2" required /></label>
                <label v-if="isChoiceQuestion(question.type)" class="wide">选项（每行一项）<textarea v-model="question.optionsText" rows="3" required /></label>
                <label class="wide">{{ question.type === 'SHORT_ANSWER' ? '参考答案' : question.type === 'FILL_BLANK' ? '标准答案' : '正确选项' }}<input v-model.trim="question.answer" :data-quiz-answer="questionIndex === 0 || undefined" maxlength="200" :placeholder="question.type === 'MULTIPLE' ? 'A,B' : question.type === 'TRUE_FALSE' ? 'TRUE' : 'A'" required /></label>
              </div>
            </article>
            <button type="button" class="nested-add" @click="addQuestion(section)">添加一道题</button>
          </div>
          <div v-else-if="section.type === 'MEDIA'" class="detail-grid"><label>媒体类型<select v-model="section.mediaItems![0].kind"><option>VIDEO</option><option>PPT</option><option>PDF</option><option>IMAGE</option><option>LINK</option></select></label><label>资源地址<input v-model.trim="section.mediaItems![0].url" type="url" placeholder="https://" /></label></div>
          <div v-else-if="section.sandbox" class="nested-editor">
            <div class="sandbox-summary"><strong>{{ sandboxLabel(section.sandbox.sandboxType) }}</strong><span>{{ section.sandbox.steps.length }} 个步骤 · {{ section.sandbox.rubricItems.length }} 个评分点</span></div>
            <section><header><strong>操作步骤</strong><button type="button" @click="addSandboxStep(section)">添加步骤</button></header><div class="compact-list"><div v-for="(step, stepIndex) in section.sandbox.steps" :key="stepIndex" class="compact-row"><input v-model.trim="step.title" aria-label="步骤名称" maxlength="120" required /><input v-model.trim="step.instruction" aria-label="步骤指导" maxlength="4000" required /><button v-if="section.sandbox.steps.length > 1" type="button" title="删除步骤" @click="removeSandboxStep(section, stepIndex)">删除</button></div></div></section>
            <section><header><strong>自动评分点</strong><button type="button" @click="addRubricItem(section)">添加评分点</button></header><div class="compact-list"><div v-for="(item, rubricIndex) in section.sandbox.rubricItems" :key="rubricIndex" class="compact-row rubric-row"><input v-model.trim="item.title" aria-label="评分点名称" maxlength="120" required /><input v-model.trim="item.description" aria-label="评分点说明" maxlength="2000" /><input v-model.number="item.points" aria-label="评分点分值" type="number" min="0" max="100" step="1" /><button v-if="section.sandbox.rubricItems.length > 1" type="button" title="删除评分点" @click="removeRubricItem(section, rubricIndex)">删除</button></div></div></section>
          </div>
        </article>
        <p class="weight-summary" :class="{ invalid: sectionWeight !== 100 }">计分区块权重：{{ sectionWeight }}%（必须为 100%）</p>
      </section>

      <div v-if="taskId && !published" class="template-save"><label>模板名称<input v-model.trim="templateTitle" maxlength="120" placeholder="例如：网店开通基础工单" /></label><button type="button" data-save-template :disabled="templateSaving || !templateTitle" @click="saveTemplate">{{ templateSaving ? '正在保存…' : '保存为模板' }}</button></div>
      <p v-if="saveState" data-save-state class="notice" role="status">{{ saveState }}</p><p v-if="saveError" class="error" role="alert">{{ saveError }}</p>
      <footer class="save-bar"><span>{{ published ? '已发布工单不可直接改写' : '所有保存都会写入 Prisma 数据库' }}</span><button type="submit" data-save-work-order :disabled="saving || published">{{ saving ? '正在保存…' : taskId ? '保存工单' : '创建工单' }}</button></footer>
    </form>
  </section>
</template>

<script setup lang="ts">
type SectionType = 'WORK_ORDER' | 'MEDIA' | 'QUIZ' | 'SANDBOX'
interface AdminClass { id: string; name: string; studentCount: number }
interface Resource { id: string; source: string; title: string; summary: string; configuration: Record<string, unknown> }
interface QuizItem { type: string; prompt: string; options: Array<{ key: string; text: string }>; optionsText?: string; answer?: string; answerKey?: { answers?: string[] }; explanation: string; points: number; sort: number; required: boolean }
interface MediaItem { kind: string; title: string; url: string; sort: number }
interface SandboxData { sandboxType: string; appKey: string; steps: Array<{ title: string; instruction: string; sort: number; required: boolean; fields: unknown[]; evidenceKey: string }>; rubricItems: Array<{ title: string; description: string; points: number; sort: number }> }
interface Section { clientKey: string; parentClientKey: string; resourceId?: string; type: SectionType; title: string; description: string; sort: number; required: boolean; weightPercent: number; questions?: QuizItem[]; mediaItems?: MediaItem[]; sandbox?: SandboxData }
interface WorkOrder { id: string; classId: string; title: string; description: string; status: string; autoScoreWeight: number; manualScoreWeight: number; timeLimitMinutes: number | null; sections: Section[] }
const props = defineProps<{ taskId?: string }>()
const classes = ref<AdminClass[]>([]), resources = ref<Resource[]>([]), sections = ref<Section[]>([])
const loading = ref(true), saving = ref(false), templateSaving = ref(false), loadError = ref(''), saveError = ref(''), saveState = ref(''), resourceSource = ref(''), published = ref(false), templateTitle = ref('')
const form = reactive({ classId: '', title: '', description: '', autoScoreWeight: 70, manualScoreWeight: 30, timeLimitMinutes: null as number | null })
const scoringSections = computed(() => sections.value.filter(section => section.type !== 'WORK_ORDER'))
const filteredResources = computed(() => resources.value.filter(resource => !resourceSource.value || resource.source === resourceSource.value))
const sectionWeight = computed(() => scoringSections.value.reduce((sum, section) => sum + Number(section.weightPercent || 0), 0))

function key(prefix: string) { return `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}` }
function rootKey() { return sections.value.find(section => section.type === 'WORK_ORDER')?.clientKey ?? 'work-order-root' }
function normalizeSort() { sections.value.forEach((section,index) => { section.sort = index }) }
function sourceLabel(value: string) { return ({ SOFTWARE_CENTER: '软件中心', SKILL_CAMP: '技能训练营', ENTERPRISE_TASK_LIBRARY: '企业任务库' } as Record<string,string>)[value] ?? value }
function typeLabel(value: SectionType) { return ({ MEDIA: '媒体学习', QUIZ: '理论考核', SANDBOX: '实操沙盘', WORK_ORDER: '工单分组' } as Record<string,string>)[value] }
function sandboxLabel(value: string) { return ({ STORE_BASICS: '店铺基础沙盘', PRODUCT_MANAGEMENT: '商品管理沙盘', STORE_DECORATION: '店铺装修沙盘', MARKETING: '营销沙盘', BUSINESS_ANALYTICS: '经营分析沙盘' } as Record<string,string>)[value] ?? value }
function addResource(resource: Resource) {
  const sandboxType = String(resource.configuration.sandboxType ?? 'STORE_BASICS')
  const appKey = String(resource.configuration.appKey ?? sandboxType.toLowerCase().replaceAll('_','-'))
  sections.value.push({ clientKey:key('sandbox'),parentClientKey:rootKey(),resourceId:resource.id,type:'SANDBOX',title:resource.title,description:resource.summary,sort:sections.value.length,required:true,weightPercent:scoringSections.value.length?0:100,sandbox:{sandboxType,appKey,steps:[{title:'完成受控配置',instruction:`按指导完成${resource.title}并保存。`,sort:0,required:true,fields:[{key:'result',label:'实训结果',required:true}],evidenceKey:`${appKey}-result`}],rubricItems:[{title:'操作结果完整',description:'按要求完成并留存操作证据。',points:100,sort:0}]}})
  normalizeSort()
}
function newQuestion(sort: number): QuizItem { return {type:'SINGLE',prompt:'请输入题干',options:[{key:'A',text:'选项 A'},{key:'B',text:'选项 B'}],optionsText:'选项 A\n选项 B',answer:'A',answerKey:{answers:['A']},explanation:'',points:100,sort,required:true} }
function addQuiz() { sections.value.push({clientKey:key('quiz'),parentClientKey:rootKey(),type:'QUIZ',title:'理论考核',description:'完成工单相关题目。',sort:sections.value.length,required:true,weightPercent:scoringSections.value.length?0:100,questions:[newQuestion(0)]}); normalizeSort() }
function addMedia() { sections.value.push({clientKey:key('media'),parentClientKey:rootKey(),type:'MEDIA',title:'知识准备',description:'完成指定媒体学习。',sort:sections.value.length,required:true,weightPercent:scoringSections.value.length?0:100,mediaItems:[{kind:'LINK',title:'学习资料',url:'',sort:0}]}); normalizeSort() }
function isChoiceQuestion(type: string) { return type === 'SINGLE' || type === 'MULTIPLE' }
function changeQuestionType(question: QuizItem) { if (question.type === 'TRUE_FALSE') { question.options=[]; question.optionsText=''; question.answer='TRUE' } else if (isChoiceQuestion(question.type) && !question.optionsText) { question.optionsText='选项 A\n选项 B'; question.answer='A' } else if (!isChoiceQuestion(question.type)) { question.options=[]; question.optionsText=''; question.answer='' } }
function addQuestion(section: Section) { section.questions?.push(newQuestion(section.questions.length)) }
function removeQuestion(section: Section, index: number) { section.questions?.splice(index,1); section.questions?.forEach((question,sort)=>{question.sort=sort}) }
function addSandboxStep(section: Section) { const sandbox=section.sandbox; if(!sandbox)return; const sort=sandbox.steps.length; sandbox.steps.push({title:`步骤 ${sort+1}`,instruction:'请输入步骤指导',sort,required:true,fields:[],evidenceKey:`${sandbox.appKey}-step-${sort+1}`}) }
function removeSandboxStep(section: Section, index: number) { section.sandbox?.steps.splice(index,1); section.sandbox?.steps.forEach((step,sort)=>{step.sort=sort}) }
function addRubricItem(section: Section) { const sandbox=section.sandbox; if(!sandbox)return; const sort=sandbox.rubricItems.length; sandbox.rubricItems.push({title:`评分点 ${sort+1}`,description:'请输入评分要求',points:0,sort}) }
function removeRubricItem(section: Section, index: number) { section.sandbox?.rubricItems.splice(index,1); section.sandbox?.rubricItems.forEach((item,sort)=>{item.sort=sort}) }
function move(index: number, direction: number) { const allIndex=index+1, target=allIndex+direction; [sections.value[allIndex],sections.value[target]]=[sections.value[target],sections.value[allIndex]]; normalizeSort() }
function remove(index: number) { sections.value.splice(index+1,1); normalizeSort() }
function applyTask(task: WorkOrder) { Object.assign(form,{classId:task.classId,title:task.title,description:task.description,autoScoreWeight:Number(task.autoScoreWeight),manualScoreWeight:Number(task.manualScoreWeight),timeLimitMinutes:task.timeLimitMinutes}); sections.value=task.sections.map(section=>({...section,weightPercent:Number(section.weightPercent),questions:section.questions?.map(question=>({...question,optionsText:question.options.map(option=>option.text).join('\n'),answer:question.answerKey?.answers?.join(',')??''}))})); published.value=task.status!=='DRAFT'; saveState.value='已保存' }
function questionOptions(question: QuizItem) { if(question.type==='TRUE_FALSE')return[{key:'TRUE',text:'正确'},{key:'FALSE',text:'错误'}]; if(!isChoiceQuestion(question.type))return[]; return (question.optionsText??'').split(/\r?\n/).map(text=>text.trim()).filter(Boolean).map((text,index)=>({key:String.fromCharCode(65+index),text})) }
function payload() { return { ...form, timeLimitMinutes: form.timeLimitMinutes || null, sections: sections.value.map(section => ({...section,questions:section.questions?.map((question,index)=>({...question,sort:index,options:questionOptions(question),answerKey:{answers:(question.answer??'').split(',').map(answer=>answer.trim()).filter(Boolean)},points:Number(question.points),optionsText:undefined,answer:undefined}))})) } }
function errorMessage(error: unknown) { const code=(error as {data?:{data?:{code?:string}}})?.data?.data?.code; return ({WORK_ORDER_WEIGHT_INVALID:'评分权重和区块权重都必须合计为 100%。',WORK_ORDER_SECTION_INVALID:'请补全区块、题目、步骤和评分点。',WORK_ORDER_INVALID:'请检查工单名称、班级、时间和数值。'} as Record<string,string>)[code??'']??'工单保存失败，请稍后重试。' }
async function load() {
  loading.value=true; loadError.value=''
  try { const [classData,resourceData]=await Promise.all([$fetch<{classes:AdminClass[]}>('/api/admin/classes'),$fetch<{resources:Resource[]}>('/api/admin/resources')]); classes.value=classData.classes; resources.value=resourceData.resources; if(props.taskId){applyTask((await $fetch<{task:WorkOrder}>(`/api/admin/tasks/${props.taskId}`)).task)}else{form.classId=classes.value[0]?.id??'';sections.value=[{clientKey:'work-order-root',parentClientKey:'',type:'WORK_ORDER',title:'综合实训工单',description:'',sort:0,required:true,weightPercent:0}]} } catch { loadError.value='编辑器数据读取失败，请确认班级权限后重试。' } finally { loading.value=false }
}
async function save() {
  saving.value=true; saveError.value=''; saveState.value=''
  try { if(props.taskId){const response=await $fetch<{task:WorkOrder}>(`/api/admin/tasks/${props.taskId}`,{method:'PATCH',headers:useCsrfHeaders(),body:payload()});applyTask(response.task);saveState.value='已保存'}else{const response=await $fetch<{task:WorkOrder}>('/api/admin/tasks',{method:'POST',headers:useCsrfHeaders({'Idempotency-Key':`work-order-ui-${crypto.randomUUID()}`}),body:payload()});await navigateTo(`/admin/tasks/${response.task.id}/edit`)} } catch(error){saveError.value=errorMessage(error)} finally { saving.value=false }
}
async function saveTemplate() {
  if (!props.taskId || !templateTitle.value) return
  templateSaving.value=true;saveError.value='';saveState.value=''
  try{await $fetch('/api/admin/task-templates',{method:'POST',headers:useCsrfHeaders({'Idempotency-Key':`template-ui-${crypto.randomUUID()}`}),body:{taskId:props.taskId,title:templateTitle.value}});saveState.value='模板已保存，可在工单模板中一键复制。';templateTitle.value=''}catch{saveError.value='模板保存失败，请稍后重试。'}finally{templateSaving.value=false}
}
onMounted(load)
</script>

<style scoped>
.editor{display:grid;gap:24px}.page-head,.resource-library>header,.sections>header,.section-top,.save-bar{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}.page-head p{margin:0 0 6px;color:#145bc2;font-size:12px;font-weight:700}.page-head h1{margin:0 0 8px;font-size:26px}.page-head span,.resource-library p,.sections p{color:#667085}.head-actions{display:flex;gap:8px}.head-actions a{padding:9px 12px;border:1px solid #cbd5e1;border-radius:5px;color:#145bc2;text-decoration:none;white-space:nowrap}form{display:grid;gap:26px}fieldset{margin:0;padding:22px;border:1px solid #e4e8ef;background:#fff}legend{padding:0 8px;font-size:17px;font-weight:700}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.form-grid label,.section-settings label,.detail-grid label,.template-save label{display:grid;gap:7px;color:#475467;font-size:13px}.form-grid .wide,.detail-grid .wide{grid-column:1/-1}input,select,textarea{width:100%;box-sizing:border-box;padding:9px 10px;border:1px solid #d0d5dd;border-radius:4px;background:#fff;color:#172033;font:inherit}textarea{resize:vertical}.resource-library,.sections{display:grid;gap:16px}.resource-library h2,.sections h2{margin:0;font-size:20px}.resource-library header p,.sections header p{margin:5px 0 0;font-size:13px}.resource-library header select{width:auto;min-width:180px}.resource-list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border-top:1px solid #e4e8ef;border-left:1px solid #e4e8ef;background:#fff}.resource-list article{display:grid;align-content:start;gap:7px;min-height:170px;padding:17px;border-right:1px solid #e4e8ef;border-bottom:1px solid #e4e8ef}.resource-list article span{color:#145bc2;font-size:11px;font-weight:700}.resource-list article p{margin:0;font-size:13px}.resource-list button,.sections button,.save-bar button,.template-save button{justify-self:start;padding:8px 12px;border:1px solid #1677ff;border-radius:4px;background:#fff;color:#145bc2;font-weight:600;cursor:pointer}.resource-list button{margin-top:auto}.sections>header>div:last-child{display:flex;gap:8px}.section-row{display:grid;gap:14px;padding:18px 0;border-top:1px solid #dfe4ea}.section-top>div:first-child{display:flex;align-items:center;gap:10px;min-width:0}.section-top span{flex:none;color:#145bc2;font-size:12px;font-weight:700}.section-top input{font-size:16px;font-weight:700}.row-actions{display:flex;gap:6px}.row-actions button{padding:6px 9px;border-color:#cbd5e1;color:#475467}.section-settings{display:grid;grid-template-columns:110px 100px minmax(200px,1fr);align-items:end;gap:14px}.section-settings .check{display:flex;align-items:center;height:38px}.section-settings .check input{width:auto}.detail-grid{display:grid;grid-template-columns:2fr 1fr;gap:14px;padding:14px;background:#f8fafc}.nested-editor{display:grid;gap:12px;padding:14px;background:#f8fafc}.nested-item,.nested-editor>section{display:grid;gap:10px;padding:12px;border:1px solid #e4e8ef;background:#fff}.nested-item>header,.nested-editor>section>header{display:flex;align-items:center;justify-content:space-between;gap:12px}.nested-item>header button,.nested-editor>section>header button,.nested-add{padding:5px 8px!important;border-color:#cbd5e1!important;color:#475467!important}.question-grid{padding:0;background:#fff}.compact-list{display:grid;gap:8px}.compact-row{display:grid;grid-template-columns:180px minmax(220px,1fr) auto;gap:8px}.compact-row.rubric-row{grid-template-columns:160px minmax(180px,1fr) 90px auto}.compact-row button{padding:7px 9px;border-color:#cbd5e1;color:#475467}.sandbox-summary{display:flex;gap:14px;padding:12px 14px;background:#eef4ff;color:#667085;font-size:13px}.sandbox-summary strong{color:#344054}.weight-summary{margin:0!important;padding:10px 12px;background:#ecfdf3;color:#067647!important;font-size:13px}.weight-summary.invalid{background:#fef3f2;color:#b42318!important}.template-save{display:grid;grid-template-columns:minmax(220px,420px) auto;align-items:end;gap:10px;p